package com.hermes.jarvis;
import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.hermes.jarvis.core.PersonaStore;
public class PersonaActivity extends AppCompatActivity{private PersonaStore s;private EditText e;private String[] files={"memory.md","soul.md","rules.md","profile.md"};private Spinner sp;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_persona);s=new PersonaStore(this);sp=findViewById(R.id.spPersonaFile);e=findViewById(R.id.etPersona);sp.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,files));sp.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,android.view.View v,int pos,long id){e.setText(s.read(files[pos]));}});findViewById(R.id.btnPersonaSave).setOnClickListener(v->{s.write(files[sp.getSelectedItemPosition()],e.getText().toString());Toast.makeText(this,"✅ "+files[sp.getSelectedItemPosition()]+" saved",Toast.LENGTH_SHORT).show();});}}
